// Normalizes incoming candidate payload fields (phone, email, name, skills)
const raw = $input.item.json;

// Clean phone number to 10 digits
let phone = (raw.phone || raw['Phone Number'] || raw.Phone || '').toString().replace(/[^0-9]/g, '');
if (phone.startsWith('91') && phone.length === 12) phone = phone.substring(2);
else if (phone.startsWith('0') && phone.length === 11) phone = phone.substring(1);

// Clean email to lowercase
const email = (raw.email || raw.email_id || raw.Email || '').toString().trim().toLowerCase();

// Clean name to title case
const name = (raw.full_name || raw.worker_name || raw.Name || '').toString().trim();
const skills = (raw.skills || raw.skill_tags || '').toString().trim();
const city = (raw.city || raw.location || raw.City || 'Unknown').toString().trim();

return [{
  json: {
    raw_input: raw,
    full_name: name,
    email: email || null,
    phone: phone || null,
    city: city,
    skills: skills,
    received_at: new Date().toISOString()
  }
}];

// Formats duplicate alert payload for notification
const existing = $input.item.json;
const incoming = $('Normalize & Sanitize Payload').item.json;

return [{
  json: {
    status: 'DUPLICATE_DETECTED',
    message: `Duplicate candidate detected for ${incoming.full_name}`,
    matched_existing_id: existing.id,
    matched_candidate_name: existing.full_name,
    matched_phone: existing.phone,
    matched_email: existing.email,
    incoming_phone: incoming.phone,
    incoming_email: incoming.email,
    data_sources: existing.data_sources,
    alert_timestamp: new Date().toISOString()
  }
}];

// Formats final successful ingestion response
const candidate = $('Normalize & Sanitize Payload').item.json;
const classification = $('LLM: Auto-Tag Skill Category').item.json;

return [{
  json: {
    status: 'SUCCESS',
    message: 'Candidate successfully ingested and categorized via AI',
    full_name: candidate.full_name,
    email: candidate.email,
    phone: candidate.phone,
    assigned_category: classification.category || 'General',
    ai_confidence: classification.confidence || 0.95,
    created_at: new Date().toISOString()
  }
}];
